class DiagnosisProbe:
  initialize(view, device)
  run_full_diagnosis(train_loader):
    preserve model training mode
    put view.model in evaluation mode
    under no_grad:
      for (_, sequence, positive, negative) in train_loader:
        features = view.log2feats(sequence)
        mask padding and invalid targets
        accumulate explicitly defined diagnostics using view.predict_score
      generate unseen-item recommendations for designated training users
    restore model training mode
    return {metrics: measured_results, metric_definitions: definitions}

